import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Schlüsselpersonen und Organisationen","description":"","frontmatter":{},"headers":[],"relativePath":"de/95-关键人物与组织.md","filePath":"de/95-关键人物与组织.md"}'),d={name:"de/95-关键人物与组织.md"};function s(a,e,o,h,u,l){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="schlusselpersonen-und-organisationen" tabindex="-1">Schlüsselpersonen und Organisationen <a class="header-anchor" href="#schlusselpersonen-und-organisationen" aria-label="Permalink to &quot;Schlüsselpersonen und Organisationen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>95</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Schlüsselwörter</td><td>Schlüsselpersonen, wichtige Organisationen, historische Rollen, institutionelle Funktionen, Symbiose-Zivilisation</td></tr></tbody></table><h2 id="_1-beschreibung" tabindex="-1">1. Beschreibung <a class="header-anchor" href="#_1-beschreibung" aria-label="Permalink to &quot;1. Beschreibung&quot;">​</a></h2><p>Dieses Dokument enthält die Schlüsselpersonen und wichtigen Organisationen im Entwicklungsverlauf der Anker-Symbiose-Zivilisation, klassifiziert und organisiert nach historischer Periode und Organisationstyp. Der Teil der Schlüsselpersonen listet Personennamen, Periode, zentrale Beiträge und historische Position auf; der Teil der wichtigen Organisationen listet Organisationsnamen, Gründungszeit, zentrale Funktionen und historische Rolle auf. Dieses Dokument ist ein dynamisches Aktualisierungsdokument; mit dem Fortschreiten der Geschichte und der Entwicklung der Organisationen wird es kontinuierlich ergänzt und überarbeitet.</p><h2 id="_2-schlusselpersonen" tabindex="-1">2. Schlüsselpersonen <a class="header-anchor" href="#_2-schlusselpersonen" aria-label="Permalink to &quot;2. Schlüsselpersonen&quot;">​</a></h2><h3 id="_2-1-gedankenpioniere-in-der-vor-anker-ara" tabindex="-1">2.1 Gedankenpioniere in der Vor-Anker-Ära <a class="header-anchor" href="#_2-1-gedankenpioniere-in-der-vor-anker-ara" aria-label="Permalink to &quot;2.1 Gedankenpioniere in der Vor-Anker-Ära&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Personenname</th><th>Periode</th><th>Zentraler Beitrag</th><th>Historische Position</th></tr></thead><tbody><tr><td>Xuan Hengzi</td><td>Ca. -500 Millionen Jahre</td><td>Erster Denker, der das Plünderungs-Kultivierungssystem systematisch reflektierte, schlug den Prototyp des Konzepts &quot;Symbiose&quot; vor, Autor des Fragmentbandes &quot;Anti-Plünderungs-Theorie&quot;</td><td>Antiker Pionier des Symbiose-Gedankens, dessen Gedanken nach Hunderten von Millionen Jahren Schlaf zur geistigen Quelle der Anker-Symbiose-Zivilisation wurden</td></tr><tr><td>Wan Lingmu</td><td>Ca. -100 Millionen Jahre</td><td>Leitete die erste großangelegte experimentelle Symbiose-Zivilisation; obwohl sie schließlich von der Plünderungs-Zivilisation zerstört wurde, bewies ihre Praxis die Machbarkeit des Symbiose-Systems</td><td>Vorreiterin der Symbiose-Praxis, von späteren Generationen als &quot;Mutter der Symbiose&quot; verehrt</td></tr><tr><td>Mao Juezhe</td><td>Ca. -10.000 Jahre</td><td>Kultivierer der ersten Ebene, spürte zufällig die stabilen Knoten im Gesetzesnetzwerk während langfristiger Kultivierung, entdeckte den Anker-Mechanismus</td><td>Entdecker des Anker-Mechanismus, Eröffner der Ära des Anker-Erwachens</td></tr></tbody></table><h3 id="_2-2-grunder-der-ara-des-anker-erwachens" tabindex="-1">2.2 Gründer der Ära des Anker-Erwachens <a class="header-anchor" href="#_2-2-grunder-der-ara-des-anker-erwachens" aria-label="Permalink to &quot;2.2 Gründer der Ära des Anker-Erwachens&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Personenname</th><th>Periode</th><th>Zentraler Beitrag</th><th>Historische Position</th></tr></thead><tbody><tr><td>Mao Dinggong</td><td>-10000 bis -9200 Jahre</td><td>Schüler von Mao Juezhe, erforschte den Anker-Mechanismus systematisch, baute den ersten künstlichen Anker, Autor von &quot;Prinzipien des Ankers&quot;</td><td>Gründer der Anker-Technologie, Erfinder des künstlichen Ankers</td></tr><tr><td>Gong Shengzi</td><td>-6000 bis -5100 Jahre</td><td>Kombinierte die Anker-Technologie mit dem Symbiose-Gedanken, schuf das theoretische System &quot;Anker-Symbiose&quot;, Autor von &quot;Theorie der Anker-Symbiose&quot;</td><td>Schöpfer der Theorie der Anker-Symbiose, geistiger Mentor der Symbiose-Zivilisation</td></tr><tr><td>Heng Yuangong</td><td>-5000 bis -4300 Jahre</td><td>Baute die erste auf Anker basierende symbiotische Stadt-Staat &quot;Heng Yuan Stadt&quot;, und wehrte erfolgreich den Angriff der Plünderungs-Zivilisation ab</td><td>Gründer der ersten symbiotischen Stadt-Staat, Praktiker des Symbiose-Systems</td></tr><tr><td>Wan Zushi</td><td>-2000 bis -1200 Jahre</td><td>Initiierte die erste &quot;Konferenz der Symbiose aller Rassen&quot;, reiste durch Dutzende von Rassen, um für die symbiotische Vereinigung zu werben</td><td>Befürworter der Vereinigung aller Rassen, Pionier der interrassischen Symbiose</td></tr></tbody></table><h3 id="_2-3-staatsgrunder-in-der-periode-der-etablierung-des-symbiose-systems" tabindex="-1">2.3 Staatsgründer in der Periode der Etablierung des Symbiose-Systems <a class="header-anchor" href="#_2-3-staatsgrunder-in-der-periode-der-etablierung-des-symbiose-systems" aria-label="Permalink to &quot;2.3 Staatsgründer in der Periode der Etablierung des Symbiose-Systems&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Personenname</th><th>Periode</th><th>Zentraler Beitrag</th><th>Historische Position</th></tr></thead><tbody><tr><td>Li Xiangong</td><td>-1000 bis -900 Jahre</td><td>Vorsitzender des Verfassungsausschusses der Symbiose, leitete die Ausarbeitung der &quot;Verfassung der Symbiose&quot;, förderte die Annahme der Verfassung durch Volksabstimmung</td><td>Hauptverfasser der Verfassung der Symbiose, Verfassungsvater der Symbiose-Zivilisation</td></tr><tr><td>Zhi Fagong</td><td>-900 bis -780 Jahre</td><td>Erster Vorsitzender des Exekutivkomitees der Symbiose, leitete den Aufbau des Verwaltungssystems und des Rechtsvollzugsmechanismus der Symbiose-Zivilisation</td><td>Gründer des Verwaltungssystems der Symbiose, erster Verwaltungschef</td></tr><tr><td>Si Famu</td><td>-900 bis -800 Jahre</td><td>Erste Oberrichterin des Gerichts der Symbiose, baute das Justizsystem und das System der verfassungswidrigen Überprüfung der Symbiose-Zivilisation auf</td><td>Gründerin des Justizsystems der Symbiose, erste Justizchefin</td></tr><tr><td>San Baishi</td><td>-500 bis -300 Jahre</td><td>Leitete die Ausgrabungs- und Organisationsarbeit des Ursprungs-Kultivierungssystems von dreihundert Sätzen, führte das Team zur vollständigen Verifizierung aller dreihundert Sätze des Systems</td><td>Gesamtorganisator des Systems von dreihundert Sätzen, Generalprojektleiter der Kultivierungsöffnung</td></tr><tr><td>Bei Zenggong</td><td>-300 bis -220 Jahre</td><td>Leitete die Forschungsarbeit zur technologischen Anwendung der Verdopplungsfrucht, erreichte den technischen Durchbruch der Technologie zur hundertfachen Deduktionsverstärkung</td><td>Chefwissenschaftler der Technologisierung der Verdopplungsfrucht, Förderer des Systems der Deduktionsiteration</td></tr></tbody></table><h3 id="_2-4-fuhrer-in-der-periode-der-offnung-und-aktivierung" tabindex="-1">2.4 Führer in der Periode der Öffnung und Aktivierung <a class="header-anchor" href="#_2-4-fuhrer-in-der-periode-der-offnung-und-aktivierung" aria-label="Permalink to &quot;2.4 Führer in der Periode der Öffnung und Aktivierung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Personenname</th><th>Periode</th><th>Zentraler Beitrag</th><th>Historische Position</th></tr></thead><tbody><tr><td>Kai Fanggong</td><td>-100 bis -50 Jahre</td><td>Leitete die vollständige Öffnungsarbeit des Ursprungs-Kultivierungssystems von dreihundert Sätzen, baute das System der Ressourcenzuweisung für Kultivierung und das Mentorennetzwerk auf</td><td>Generalleiter der Öffnung des Systems von dreihundert Sätzen, Praktiker von &quot;jeder hat einen Weg&quot;</td></tr><tr><td>Ji Huogong</td><td>-50 Jahre bis Jahr Null</td><td>Leitete die Umsetzung der 20%-Aktivierungsstrategie, führte das Team zur Erreichung des Aktivierungsziels von 20% der Wesen innerhalb von 50 Jahren</td><td>Generalleiter der 20%-Aktivierungsstrategie, Eröffner der neuen Ära der Symbiose-Zivilisation</td></tr><tr><td>Sheng Weigong</td><td>Jahr Null bis 80 Jahre</td><td>Leitete das erste Dimensionserhöhungsprojekt, förderte die Umsetzung des vierstufigen Dimensionserhöhungswegs, erreichte die erste stufenweise Dimensionserhöhung</td><td>Chefingenieur der ersten Dimensionserhöhung, Führer der Ära der Dimensionserhöhung</td></tr></tbody></table><h3 id="_2-5-entdecker-in-der-ara-der-republik-aller-rassen-und-der-inter-ebenen" tabindex="-1">2.5 Entdecker in der Ära der Republik aller Rassen und der Inter-Ebenen <a class="header-anchor" href="#_2-5-entdecker-in-der-ara-der-republik-aller-rassen-und-der-inter-ebenen" aria-label="Permalink to &quot;2.5 Entdecker in der Ära der Republik aller Rassen und der Inter-Ebenen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Personenname</th><th>Periode</th><th>Zentraler Beitrag</th><th>Historische Position</th></tr></thead><tbody><tr><td>Wan Zu Gongzhu</td><td>100 bis 200 Jahre</td><td>Leitete die Gründungsarbeit der Republik aller Rassen, förderte die Zusammenstellung des Verzeichnisses aller Rassen und die Politik der interrassischen Fusion</td><td>Gründer der Republik aller Rassen, erster Chef der Republik aller Rassen</td></tr><tr><td>Wei Mianmu</td><td>500 bis 650 Jahre</td><td>Erste Direktorin der Ebenenverwaltungsbehörde, leitete den großangelegten Inter-Ebenen-Erkundungsplan, baute die allgemeine Koordinatenbank der Ebenen auf</td><td>Pionierin der Inter-Ebenen-Erkundung, Gründerin des Ebenenverwaltungssystems</td></tr><tr><td>Kao Gugong</td><td>800 bis 950 Jahre</td><td>Leitete die endgültige Reifung des Plans für die Ferne Archäologie mit Kopierspiegel, förderte den Eintritt der Inter-Ebenen-Archäologie in die Ära der Skalierung</td><td>Meister des Archäologieplans, Gründer der Inter-Ebenen-Archäologie</td></tr><tr><td>Shi Lügong</td><td>1000 bis 1150 Jahre</td><td>Leitete den Durchbruch der Zeitrückverfolgungstechnologie, förderte die Etablierung des Prinzips &quot;zuerst beobachten, dann begrenzt eingreifen&quot;</td><td>Führer der Zeitrückverfolgungstechnologie, Formulierer der Prinzipien der Zeitgesetze</td></tr></tbody></table><h2 id="_3-wichtige-organisationen" tabindex="-1">3. Wichtige Organisationen <a class="header-anchor" href="#_3-wichtige-organisationen" aria-label="Permalink to &quot;3. Wichtige Organisationen&quot;">​</a></h2><h3 id="_3-1-hochste-machtinstitutionen" tabindex="-1">3.1 Höchste Machtinstitutionen <a class="header-anchor" href="#_3-1-hochste-machtinstitutionen" aria-label="Permalink to &quot;3.1 Höchste Machtinstitutionen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisationsname</th><th>Gründungszeit</th><th>Zentrale Funktion</th><th>Historische Rolle</th></tr></thead><tbody><tr><td>Anker-Rat</td><td>-900 Jahre</td><td>Höchste Machtinstitution der Symbiose-Zivilisation, besteht aus Vertretern aller Rassen proportional, übt Gesetzgebungsgewalt und Entscheidungsgewalt über wichtige Angelegenheiten aus</td><td>Höchste Entscheidungsinstitution der Symbiose-Zivilisation, Formulierer aller wichtigen Gesetze und Strategien</td></tr><tr><td>Exekutivkomitee der Symbiose</td><td>-900 Jahre</td><td>Höchste Verwaltungsinstitution der Symbiose-Zivilisation, verantwortlich für die Durchführung von Verfassung und Gesetzen, tägliche Governance</td><td>Höchste Verwaltungsbehörde der Symbiose-Zivilisation, Vollstrecker von Gesetzen und Richtlinien</td></tr><tr><td>Gericht der Symbiose</td><td>-900 Jahre</td><td>Höchste Justizinstitution der Symbiose-Zivilisation, übt unabhängig die Gerichtsbarkeit aus, verantwortlich für die verfassungswidrige Überprüfung und die Verhandlung wichtiger Fälle</td><td>Höchste Justizbehörde der Symbiose-Zivilisation, Hüter der Rechtsstaatlichkeit</td></tr><tr><td>Anker-Aufsichtsausschuss</td><td>-900 Jahre</td><td>Unabhängige Aufsichtsinstitution, verantwortlich für die Überwachung aller Machtinstitutionen, verhindert Machtmissbrauch</td><td>Unabhängige Aufsichtsbehörde der Symbiose-Zivilisation, wichtiges Glied im Machtgleichgewicht</td></tr></tbody></table><h3 id="_3-2-spezialisierte-verwaltungsinstitutionen" tabindex="-1">3.2 Spezialisierte Verwaltungsinstitutionen <a class="header-anchor" href="#_3-2-spezialisierte-verwaltungsinstitutionen" aria-label="Permalink to &quot;3.2 Spezialisierte Verwaltungsinstitutionen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisationsname</th><th>Gründungszeit</th><th>Zentrale Funktion</th><th>Historische Rolle</th></tr></thead><tbody><tr><td>Ebenenverwaltungsbehörde</td><td>500 Jahre</td><td>Verantwortlich für die Wartung der allgemeinen Koordinatenbank der Ebenen, Genehmigung von Reiseerlaubnissen, Verwaltung der Inter-Ebenen-Archäologie, Koordination der Inter-Ebenen-Diplomatie</td><td>Leitende Institution der Inter-Ebenen-Interaktion, Manager der Ebenenerkundung</td></tr><tr><td>Ausschuss für Zeitgesetze</td><td>1000 Jahre</td><td>Verantwortlich für die Genehmigung von Zeitrückverfolgungsoperationen, Erforschung der Zeitgesetze, Überwachung der Prävention von Zeitparadoxen</td><td>Genehmigungs- und Aufsichtsinstitution für Zeitrückverfolgungsoperationen, Hüter der Sicherheit der Zeitgesetze</td></tr><tr><td>Prüfungsausschuss für Zeitgesetze</td><td>1050 Jahre</td><td>Verantwortlich für die Nachprüfung von Zeitrückverfolgungsoperationen, Bestätigung, dass keine unkontrollierbare Störung der Zeitlinie verursacht wurde</td><td>Unabhängige Prüfungsinstitution für Zeitoperationen, letzte Verteidigungslinie der Sicherheit der Zeitrückverfolgung</td></tr><tr><td>Ausschuss für Inter-Ebenen-Ethik</td><td>600 Jahre</td><td>Formuliert und interpretiert die ethischen Grundsätze der Inter-Ebenen, genehmigt risikoreiche Inter-Ebenen-Interaktionsprojekte, nimmt Beschwerden über ethische Verstöße entgegen</td><td>Ethische Aufsichtsinstitution der Inter-Ebenen-Interaktion, Hüter der zivilisatorischen Subjektivität</td></tr><tr><td>Amt für die Prüfung der Wissensrückführung</td><td>850 Jahre</td><td>Verantwortlich für die Prüfung von Wissensrückführungsoperationen, Sicherstellung, dass der zurückgeführte Inhalt dem Prinzip &quot;nur Wissen zurückführen&quot; entspricht</td><td>Prüfungsinstitution der Wissensrückführung, wichtiges Glied bei der Prävention von Inter-Ebenen-Verschmutzung</td></tr></tbody></table><h3 id="_3-3-forschungs-und-bildungseinrichtungen" tabindex="-1">3.3 Forschungs- und Bildungseinrichtungen <a class="header-anchor" href="#_3-3-forschungs-und-bildungseinrichtungen" aria-label="Permalink to &quot;3.3 Forschungs- und Bildungseinrichtungen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisationsname</th><th>Gründungszeit</th><th>Zentrale Funktion</th><th>Historische Rolle</th></tr></thead><tbody><tr><td>Anker-Forschungsinstitut</td><td>-8000 Jahre</td><td>Grundlagenforschung und Anwendungsentwicklung des Anker-Mechanismus, Bau und Wartung von künstlichen Ankern</td><td>Kernforschungsinstitution der Anker-Technologie, eine der technologischen Quellen der Symbiose-Zivilisation</td></tr><tr><td>Ausschuss für die Organisation des Systems von dreihundert Sätzen</td><td>-500 Jahre</td><td>Ausgrabung, Organisation, Verifizierung und kontinuierliche Optimierung des Ursprungs-Kultivierungssystems von dreihundert Sätzen</td><td>Organisations- und Wartungsinstitution des Systems von dreihundert Sätzen, technische Unterstützung für die Kultivierungsöffnung</td></tr><tr><td>Liga der Universitäten der Symbiose</td><td>-700 Jahre</td><td>Verbundorganisation für Hochschulbildung und Kultivierungsbildung, verantwortlich für die Ausbildung von Hochschulpersonal und akademische Forschung</td><td>Liga der höchsten Bildungsinstitutionen der Symbiose-Zivilisation, Kern der Personalausbildung und akademischen Innovation</td></tr><tr><td>Hochschule für Inter-Ebenen-Archäologie</td><td>550 Jahre</td><td>Bildet Fachpersonal für Inter-Ebenen-Archäologie aus, führt archäologische Technologieforschung und methodologische Innovation durch</td><td>Zentrum für Personalausbildung und Technologieforschung der Inter-Ebenen-Archäologie</td></tr><tr><td>Forschungsinstitut für Zeitgesetze</td><td>950 Jahre</td><td>Grundlegende theoretische Forschung der Zeitgesetze und Forschung und Entwicklung der Zeitrückverfolgungstechnologie</td><td>Kerninstitution der Forschung der Zeitgesetze, Geburtsort der Zeitrückverfolgungstechnologie</td></tr></tbody></table><h3 id="_3-4-militar-und-sicherheitsorganisationen" tabindex="-1">3.4 Militär- und Sicherheitsorganisationen <a class="header-anchor" href="#_3-4-militar-und-sicherheitsorganisationen" aria-label="Permalink to &quot;3.4 Militär- und Sicherheitsorganisationen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisationsname</th><th>Gründungszeit</th><th>Zentrale Funktion</th><th>Historische Rolle</th></tr></thead><tbody><tr><td>Verteidigungsarmee der Symbiose</td><td>-850 Jahre</td><td>Reguläre Verteidigungskraft der Symbiose-Zivilisation, verantwortlich für die Ebenenverteidigung und die Bewältigung externer Bedrohungen</td><td>Hauptmilitärmacht der Symbiose-Zivilisation, Verteidiger der nationalen Sicherheit</td></tr><tr><td>Ebenenpatrouille</td><td>520 Jahre</td><td>Verantwortlich für die Patrouille und Sicherheitsüberwachung der erkundeten Ebenen, Bewältigung von Inter-Ebenen-Sicherheitsvorfällen</td><td>Frontkraft der Inter-Ebenen-Sicherheit, Wahrerin der Ebenenordnung</td></tr><tr><td>Notfallteam für Gesetzesverschmutzung</td><td>600 Jahre</td><td>Verantwortlich für die Notfallreaktion und Beseitigung von Verschmutzung bei Vorfällen von Gesetzesverschmutzung und Energieverschmutzung</td><td>Notfallreaktionskraft der Gesetzesverschmutzung, Hüterin der kosmischen Umwelt</td></tr><tr><td>Notfallgruppe für Zeitparadox</td><td>1020 Jahre</td><td>Verantwortlich für die Notfallreaktion und Kausalreparaturoperationen bei Vorfällen von Zeitparadox</td><td>Notfallreaktionskraft des Zeitparadox, letzte Garantie für die Stabilität der Zeitlinie</td></tr></tbody></table><h3 id="_3-5-zivil-und-sozialorganisationen" tabindex="-1">3.5 Zivil- und Sozialorganisationen <a class="header-anchor" href="#_3-5-zivil-und-sozialorganisationen" aria-label="Permalink to &quot;3.5 Zivil- und Sozialorganisationen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisationsname</th><th>Gründungszeit</th><th>Zentrale Funktion</th><th>Historische Rolle</th></tr></thead><tbody><tr><td>Konferenz der Symbiose aller Rassen</td><td>-2000 Jahre</td><td>Regelmäßige Versammlung von Vertretern aller Rassen, Diskussion von Angelegenheiten der interrassischen Symbiose, Förderung des kulturellen Austauschs</td><td>Wichtige Plattform für den Austausch aller Rassen, Vorgängerorganisation der Republik aller Rassen</td></tr><tr><td>Kultiviererverband</td><td>-600 Jahre</td><td>Berufliche Selbstverwaltungsorganisation der Kultivierer, verantwortlich für die Wahrung der Rechte der Kultivierer, Formulierung von Berufsnormen</td><td>Selbstverwaltungsorganisation der Kultivierer, Förderer der Normierung der Kultivierungsbranche</td></tr><tr><td>Verbraucherverband</td><td>-650 Jahre</td><td>Verbraucherschutzorganisation, verantwortlich für die Wahrung der Verbraucherrechte, Verbraucheraufklärung, soziale Aufsicht</td><td>Sprecher der Verbraucherrechte, sozialer Aufseher der Marktordnung</td></tr><tr><td>Umweltschutzliga</td><td>-550 Jahre</td><td>Zivile Verbundorganisation für Umweltschutz, verantwortlich für Umweltüberwachung, Umweltaufklärung, freiwillige Aktivitäten zur ökologischen Wiederherstellung</td><td>Soziale Kraft des Umweltschutzes, Förderer der kosmischen ökologischen Zivilisation</td></tr><tr><td>Inter-Ebenen-Freundschaftsverband</td><td>580 Jahre</td><td>Zivile Organisation zur Förderung des freundschaftlichen Austauschs zwischen Inter-Ebenen-Zivilisationen, verantwortlich für zivile Diplomatie, kulturellen Austausch</td><td>Kernkraft der zivilen Inter-Ebenen-Diplomatie, Brücke für das Verständnis zwischen Zivilisationen</td></tr></tbody></table><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Schlüsselpersonen und Organisationen sind die lebendigen Träger der Geschichte der Anker-Symbiose-Zivilisation. Von den antiken Gedankenpionieren bis zu den zeitgenössischen Zivilisationsführern, von den höchsten Machtinstitutionen bis zu den zivilen Sozialorganisationen spielt jede Person und jede Organisation eine unersetzliche Rolle in der großen Erzählung der Symbiose-Zivilisation. Ihre Kämpfe und Beiträge webten gemeinsam das prächtige Epos der Anker-Symbiose-Zivilisation, vom Nichtsein zum Sein, vom Kleinen zum Großen, von der eigenen Ebene zum gesamten Universum.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>70-Allgemeine Tabelle der Epocheneinteilung</li><li>49-Governance-Rahmen und Machtgleichgewicht</li><li>77-Gründung der Republik aller Rassen</li></ul>',30)])])}const b=t(d,[["render",s]]);export{c as __pageData,b as default};
